<script setup>
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useQuasar } from 'quasar'
import { io } from 'socket.io-client'
import { api, apiBaseURL } from 'boot/axios'
import AuthDialog from 'components/AuthDialog.vue'
const router = useRouter(), route = useRoute(), $q = useQuasar()
const loginOpen = ref(false), confirming = ref(false), paymentMessage = ref(''), buying = ref(false), checkoutOpen = ref(false), order = ref(null), purchased = ref(false)
const offer = ref({ available: false, priceCents: null, originalPriceCents: null }), missing = ref({})
const checkoutReturn = computed(() => typeof route.query.order_nsu === 'string' && typeof route.query.transaction_nsu === 'string' && typeof (route.query.slug || route.query.invoice_slug) === 'string')
const authReturnPath = computed(() => checkoutReturn.value ? route.fullPath : '/whatsappbotbuilder?comprar=1')
const money = cents => cents == null ? 'Consulte disponibilidade' : (Number(cents) / 100).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
const headers = () => ({ headers: { Authorization: `Bearer ${localStorage.getItem('aito_user_token') || ''}` } })
let socket, timer
function connect() {
  if (socket || !localStorage.getItem('aito_user_token')) return
  const url = new URL(apiBaseURL, window.location.origin)
  socket = io(`${url.origin}/products`, { auth: { token: localStorage.getItem('aito_user_token') }, transports: ['websocket', 'polling'], reconnectionDelay: 1500 })
  socket.on('purchase.updated', event => { if (!order.value || order.value.orderNsu === event.orderNsu) refreshPurchase() })
  socket.on('connect', () => { if (checkoutOpen.value) refreshPurchase() })
}
async function refreshPurchase() {
  if (!localStorage.getItem('aito_user_token')) return
  try { const data = (await api.get('/products/whatsappbotbuilder', headers())).data.data; purchased.value = data.licenses.some(item => item.active); if (order.value) order.value = data.orders.find(item => item.orderNsu === order.value.orderNsu) || order.value } catch { /* o próximo evento ou consulta reconcilia a confirmação */ }
}
async function buy() {
  if (buying.value) return
  if (!localStorage.getItem('aito_user_token')) { loginOpen.value = true; return }
  checkoutOpen.value = true; buying.value = true; paymentMessage.value = ''; connect()
  clearInterval(timer); timer = setInterval(() => { if (checkoutOpen.value) refreshPurchase() }, 15000)
  try {
    await refreshPurchase()
    if (!purchased.value) order.value = (await api.post('/products/whatsappbotbuilder/checkout', {}, headers())).data.data
  } catch (error) { paymentMessage.value = error.response?.data?.message || 'Não foi possível abrir o checkout. Tente novamente.' }
  finally { buying.value = false }
}
async function confirmCheckout() {
  if (!checkoutReturn.value || confirming.value) return
  if (!localStorage.getItem('aito_user_token')) { loginOpen.value = true; paymentMessage.value = 'Entre com a conta usada na compra para confirmar o pagamento.'; return }
  checkoutOpen.value = true; confirming.value = true; paymentMessage.value = ''; connect()
  try {
    await api.post('/products/whatsappbotbuilder/confirm', { order_nsu: route.query.order_nsu, transaction_nsu: route.query.transaction_nsu, slug: route.query.slug || route.query.invoice_slug }, headers())
    await refreshPurchase()
    $q.notify({ type: 'positive', message: 'Pagamento confirmado. Seu código e token estão em Meus produtos.' })
  } catch (error) { paymentMessage.value = error.response?.data?.message || 'Pagamento aguardando confirmação. Consulte novamente em instantes.' }
  finally { confirming.value = false }
}
function onAuthenticated() { connect(); if (checkoutReturn.value) confirmCheckout(); else buy() }
onMounted(async () => { try { offer.value = (await api.get('/products/whatsappbotbuilder/public')).data.data } catch { paymentMessage.value = 'Oferta indisponível no momento.' } connect(); if (checkoutReturn.value) confirmCheckout(); else if (route.query.comprar === '1') buy() })
onBeforeUnmount(() => { socket?.disconnect(); clearInterval(timer) })
</script>
<template>
<q-layout view="hHh lpR fFf"><q-page-container><q-page class="product">
<header><router-link to="/" class="brand">AITO<span>SOFTWARES</span></router-link><router-link to="/app?tab=products">Meus produtos ↗</router-link></header>
<main class="hero"><div class="copy"><span class="eyebrow">SEU ATENDIMENTO. SUAS REGRAS. SEU CÓDIGO.</span><h1>Seu WhatsApp pode trabalhar <em>antes de você responder.</em></h1><p>Receba clientes, faça a triagem, use IA e cobre pelo WhatsApp. Monte cada etapa num editor visual e acompanhe tudo no seu próprio painel.</p><div class="price"><s v-if="offer.originalPriceCents > offer.priceCents">{{ money(offer.originalPriceCents) }}</s><strong>{{ money(offer.priceCents) }}</strong><span>Código fonte + licença para uma instalação</span></div><q-btn unelevated no-caps color="teal-6" size="lg" icon="mdi-cart-outline" label="Quero meu BotBuilder" :loading="buying" :disable="!offer.available" @click="buy" /><div class="trust"><q-icon name="mdi-shield-check-outline" />Pagamento no checkout InfinitePay · Liberação após confirmação</div><div class="highlights"><span>Editor visual</span><span>OpenAI + InfinitePay</span><span>Personalizável</span></div></div>
<div class="hero-devices"><div class="laptop"><div class="screen"><img v-if="!missing.notebook1" src="/wppbotbuilder-notebook1.jpg" alt="Painel do WhatsApp BotBuilder no computador" @error="missing.notebook1 = true"><div v-else class="screen-placeholder"><q-icon name="mdi-sitemap-outline" size="54px" /><strong>Desenhe sua operação</strong><span>Fluxos · Conversas · Integrações</span></div></div><div class="laptop-base"></div></div><div class="phone"><div class="phone-camera"></div><img v-if="!missing.phone1" src="/wppbotbuilder-phone1.jpg" alt="WhatsApp BotBuilder no celular" @error="missing.phone1 = true"><div v-else class="screen-placeholder"><q-icon name="mdi-whatsapp" size="46px" /><strong>Atenda de onde estiver</strong><span>Seu painel no celular</span></div></div><span class="device-note">Uma operação conectada. No computador e no celular.</span></div></main>
<section class="benefits"><article><q-icon name="mdi-sitemap-outline" /><h2>Transforme a conversa em fluxo.</h2><p>Mensagens, decisões, arquivos, ações e pagamentos. Simule antes de aplicar, clone cards e importe ou exporte seus fluxos.</p></article><article><q-icon name="mdi-brain" /><h2>IA com o contexto do seu negócio.</h2><p>Escolha modelos, configure instruções e referências, controle a memória de cada chat e acompanhe o consumo em dólar e real.</p></article><article><q-icon name="mdi-code-braces" /><h2>Um produto que se adapta a você.</h2><p>Personalize marca, mensagens e integrações no painel. O código fonte acompanha a licença para sua instalação.</p></article></section>
<section class="showcase"><div><span class="eyebrow">DO PRIMEIRO CONTATO AO PAGAMENTO</span><h2>Menos tarefas repetidas.<br>Mais controle do atendimento.</h2><p>Atendimento humano e bot no mesmo lugar. Organize contatos, receba arquivos, gere links de pagamento e continue o fluxo após a confirmação da compra.</p><q-btn outline no-caps color="teal-3" label="Começar com meu BotBuilder" :disable="!offer.available" @click="buy" /></div><div class="second-devices"><div class="phone"><div class="phone-camera"></div><img v-if="!missing.phone2" src="/wppbotbuilder-phone2.jpg" alt="Conversas e atendimento no celular" @error="missing.phone2 = true"><div v-else class="screen-placeholder"><q-icon name="mdi-chat-outline" size="46px" /><strong>Conversa sob controle</strong></div></div><div class="laptop"><div class="screen"><img v-if="!missing.notebook2" src="/wppbotbuilder-notebook2.jpg" alt="Editor visual no computador" @error="missing.notebook2 = true"><div v-else class="screen-placeholder"><q-icon name="mdi-monitor-dashboard" size="54px" /><strong>Seu painel. Sua marca.</strong></div></div><div class="laptop-base"></div></div></div></section>
<section class="guide" id="instalacao"><span class="eyebrow">DA COMPRA AO PRIMEIRO FLUXO</span><h2>Comece em três etapas.</h2><div class="steps"><article><b>01</b><h3>Compre com InfinitePay</h3><p>Entre ou crie sua conta de estudante. Conclua o pagamento no checkout InfinitePay.</p></article><article><b>02</b><h3>Receba seu código e token</h3><p>A confirmação libera o ZIP e a licença em Meus produtos. Uma instalação por licença.</p></article><article><b>03</b><h3>Instale e personalize</h3><p>Extraia o ZIP, preencha AITO_LICENSE_TOKEN no .env e inicie com Docker. Conecte seu WhatsApp e desenhe o fluxo.</p></article></div><details><summary>O que preciso para usar?</summary><p>Docker Desktop ou um servidor com Docker, WhatsApp para conectar e sua licença ativa. IA exige sua chave e créditos OpenAI. Campanhas pela API oficial da Meta exigem uma integração e conta próprias; a sessão WhatsApp Web deste produto usa QR Code.</p></details></section>
<footer>WhatsApp BotBuilder · AitoSoftwares <router-link to="/app?tab=products">Já comprei: acessar meus produtos →</router-link></footer>
<div class="buy-floating"><span><small>Código fonte + licença</small><strong>{{ money(offer.priceCents) }}</strong></span><q-btn unelevated no-caps color="teal-6" icon="mdi-cart-outline" label="Comprar agora" :loading="buying" :disable="!offer.available" @click="buy" /></div>
<q-dialog v-model="checkoutOpen"><q-card class="checkout-card"><q-card-section><div class="checkout-head"><h3>{{ purchased ? 'Seu BotBuilder está liberado' : 'Seu checkout InfinitePay' }}</h3><q-btn flat round icon="mdi-close" v-close-popup /></div><p v-if="buying || confirming"><q-spinner color="teal-3" /> {{ confirming ? 'Confirmando pagamento…' : 'Preparando seu link seguro…' }}</p><template v-else-if="purchased"><q-icon name="mdi-check-decagram" size="48px" color="teal-3" /><p>Compra confirmada. Seu token e o código fonte estão em Meus produtos.</p><q-btn no-caps color="teal-6" label="Acessar meu produto" to="/app?tab=products" /></template><template v-else><p>O pagamento é realizado no checkout da InfinitePay. Seus dados de cartão são informados diretamente ao provedor.</p><q-btn v-if="order?.checkoutUrl" no-caps color="teal-6" icon="mdi-lock-outline" label="Abrir checkout seguro" :href="order.checkoutUrl" target="_blank" rel="noopener noreferrer" /><p v-if="order" class="status">Aguardando confirmação. A liberação aparece aqui automaticamente, mesmo que você pague em outra aba.</p><q-btn v-if="order" flat no-caps color="teal-2" label="Consultar pagamento" @click="refreshPurchase" /></template><p v-if="paymentMessage" role="alert">{{ paymentMessage }}</p><q-btn v-if="paymentMessage && !purchased" flat no-caps color="teal-2" label="Tentar novamente" @click="checkoutReturn ? confirmCheckout() : buy()" /></q-card-section></q-card></q-dialog>
<AuthDialog v-model="loginOpen" audience="user" :return-path="authReturnPath" @authenticated="onAuthenticated" />
</q-page></q-page-container></q-layout>
</template>
